import{_ as i}from"./chunks/hamburger_menu.BLyto8gA.js";import{_ as o,a as n,b as s,c as r,d as p,e as l}from"./chunks/M-S-SW-MB-I5.BZKmfHD5.js";import{_ as a}from"./chunks/ON.DXVlsWbj.js";import{_ as t}from"./chunks/OFF.BrU7kQE-.js";import{_ as d}from"./chunks/EN.P9aPnFBv.js";import{_ as c,o as h,c as m,a3 as u}from"./chunks/framework.g9mfNVRQ.js";const z=JSON.parse('{"title":"MiBand","description":"","frontmatter":{},"headers":[],"relativePath":"smartwatch/miband.md","filePath":"smartwatch/miband.md"}'),y={name:"smartwatch/miband.md"};function f(b,e,g,w,v,x){return h(),m("div",null,[...e[0]||(e[0]=[u('<div class="admonition xdrip"><p class="admonition-title"><img src="'+i+'" style="zoom:75%;"></p><p> <img src="https://raw.githubusercontent.com/NightscoutFoundation/xDrip/master/app/src/main/res/drawable-xhdpi/ic_watch_grey600_48dp.png" style="width:5%;"> Smart Watch Features<br>   MiBand</p></div><p>xDrip Official Release supports MiBand 2, 3, 4 and broadcast to <a href="https://bigdigital.home.blog/2022/06/16/watchdrip-a-new-application-for-xdrip-watch-integration" target="_blank" rel="noreferrer">WatchDrip+</a> for other smartbands.</p><div class="info custom-block"><p class="custom-block-title">Prerequisite</p><p>Make sure you have BG readings in xDrip before trying to have them on your watch.<br> If xDrip doesn&#39;t receive readings on your phone, they won&#39;t be displayed on the watch.</p></div><h2 id="install" tabindex="-1">Install <a class="header-anchor" href="#install" aria-label="Permalink to &quot;Install&quot;">​</a></h2><h3 id="obtain-an-authentication-key" tabindex="-1">Obtain an authentication key <a class="header-anchor" href="#obtain-an-authentication-key" aria-label="Permalink to &quot;Obtain an authentication key&quot;">​</a></h3><h4 id="if-you-already-paired-your-watch-with-the-vendor-app" tabindex="-1">If you already paired your watch with the vendor app <a class="header-anchor" href="#if-you-already-paired-your-watch-with-the-vendor-app" aria-label="Permalink to &quot;If you already paired your watch with the vendor app&quot;">​</a></h4><ul><li><p>Unpair the watch.</p></li><li><p>Uninstall MiFit or Zepp, or whatever app you used to connect your watch.</p></li><li><p><strong>Delete the old key files</strong> (use a file browser on your phone) in the phone memory <code>freemyband</code> folder.<br> Recommended if you can&#39;t get xDrip to connect to the watch.<br><em>Note: the name below is an example</em></p></li></ul><img src="'+o+'" style="zoom:75%;"><h4 id="install-the-patched-app-matching-your-watch" tabindex="-1">Install the patched app matching your watch <a class="header-anchor" href="#install-the-patched-app-matching-your-watch" aria-label="Permalink to &quot;Install the patched app matching your watch&quot;">​</a></h4><p>Go to <a href="https://www.freemyband.com/" target="_blank" rel="noreferrer">https://www.freemyband.com/</a></p><p>Download and install <a href="https://www.freemyband.com/2019/08/amazfit-gtr-auth-key.html" target="_blank" rel="noreferrer">Zepp</a> for Amazfit watches.<br> (or)<br> Download and install <a href="https://www.freemyband.com/2019/08/mi-band-4-auth-key.html" target="_blank" rel="noreferrer">MiFit</a> for Xiaomi smartbands.</p><p>Authenticate with mail and password. Create an account if necessary.</p><p>Pair your smartband.</p><p>Enable watch visibility. If you don&#39;t find this option make sure you have set your age to 18 or above.</p><p>Check a key file was created in the phone memory <code>freemyband</code> folder.</p><p>You can uninstall the patched app. This is not mandatory. If you want to install the original app, use the same email account to log in.</p><h2 id="not-using-watchdrip" tabindex="-1">Not using WatchDrip+ <a class="header-anchor" href="#not-using-watchdrip" aria-label="Permalink to &quot;Not using WatchDrip+&quot;">​</a></h2><div class="info custom-block"><p class="custom-block-title">Only MiBand 2, 3 and 4</p></div><h3 id="setup-xdrip" tabindex="-1">Set up xDrip <a class="header-anchor" href="#setup-xdrip" aria-label="Permalink to &quot;Set up xDrip {#setup-xdrip}&quot;">​</a></h3><p>Switch the MiBand feature on. Keep your watch close to your phone until it gets detected.</p><div class="admonition xdripitem"><p class="admonition-title">Use MiBand Band <span class="symbol"><img src="'+a+'" style="zoom:75%;"></span></p></div><img src="'+n+'" style="zoom:80%;"><p>Mac Address should populate automatically.</p><div class="admonition xdripitem"><p class="admonition-title">Mac address (FF:EE:DD:CC:BB:AA)</p><p> Leave empty for auto search</p></div><p><strong>If it doesn&#39;t</strong> (unexpected)<strong>:</strong><br> Delete the file(s) in the <code>freemyband</code> folder.<br> Open the patched watch app.<br> Retry: switch off then on the MiBand feature.</p><p>You can also try to enter the watch mac address manually. You will find it in the filename in the <code>freemyband</code> folder.<br> For example if the name is <code>mibandFFEEDDCCBBAA.txt</code> the corresponding mac address will be <code>FF:EE:DD:CC:BB:AA</code>.</p><img src="'+s+'" style="zoom:75%;"><p>Keep an eye on toast messages: during smartwatch authentication you should see the following:</p><img src="'+r+'" style="zoom:75%;"><p>If authorization fails, delete the file(s) in the <code>freemyband</code> folder and open the patched app to regenerate it.</p><img src="'+p+'" style="zoom:75%;"><p>If xDrip can&#39;t get the authentication key automatically, you can try to insert it manually. You will find it by editing the file.</p><img src="'+l+'" style="zoom:75%;"><p>Make sure the watch is connected and matches the mac address before manually entering the key.</p><div class="admonition xdripitem"><p class="admonition-title">Auth Key</p><p> Set the auth key for MiBand4 (To get auth key, follow the instructions on <a href="https://www.freemyband.com/2019/08/mi-band-4-auth-key.html" target="_blank" rel="noreferrer">https://www.freemyband.com</a>)</p></div><p>Once connected and authenticated, enable Send Readings. Wait for the next value in xDrip, the watchface should update.</p><div class="admonition xdripitem"><p class="admonition-title">Send readings <span class="symbol"><img src="'+a+'" style="zoom:75%;"></span></p><p> Appropriate the watch date to represent glucose values. Better with mmol/l - see documentation</p></div><p>To force the watch to update, you can manually send a reading. Look carefully at toast messages.</p><div class="admonition xdripitem"><p class="admonition-title">Update BG manually</p></div><p>If you have trouble displaying the graph, try to disable high MTU values.</p><div class="admonition xdripitem"><p class="admonition-title">Disable hight MTU values <span class="symbol"><img src="'+t+'" style="zoom:75%;"></span></p></div><h3 id="features" tabindex="-1">Features <a class="header-anchor" href="#features" aria-label="Permalink to &quot;Features&quot;">​</a></h3><div class="admonition xdripitem"><p class="admonition-title">Use MiBand Band <span class="symbol"><img src="'+a+'" style="zoom:75%;"></span></p><p> Sync Data with MiBand fitness bands</p></div><p>You can enable and disable MiBand integration with the main switch. When troubleshooting don&#39;t hesitate to turn it off then on to restart it.</p><div class="admonition xdripitem"><p class="admonition-title">Mac address</p><p> Leave empty for auto search</p></div><p>The watch mac address should be detected automatically when the field is left empty. You can manually edit it and write the 6 two-digit hex values, colon separated, of your watch.</p><div class="admonition xdripitem"><p class="admonition-title">Auth Key</p><p> Set the auth key for MiBand4 (To get auth key, follow the instructions on <a href="https://www.freemyband.com/2019/08/mi-band-4-auth-key.html" target="_blank" rel="noreferrer">https://www.freemyband.com</a>)</p></div><p>When a valid mac address is found you will also see the key field. If it&#39;s not filled automatically you can manually enter the 32-character authentication key.</p><div class="admonition xdripitem"><p class="admonition-title">Send readings <span class="symbol"><img src="'+a+'" style="zoom:75%;"></span></p><p> Appropriate the watch date to represent glucose values. Better with mmol/l - see documentation</p></div><p>You must enable this to have readings sent to the watch.</p><div class="admonition xdripitem"><p class="admonition-title">Vibrate on readings <span class="symbol"><img src="'+a+'" style="zoom:75%;"></span></p></div><div class="admonition xdripitem"><p class="admonition-title">Send Alarms <span class="symbol"><img src="'+a+'" style="zoom:75%;"></span></p><p> Send notifications to the band for glucose alarms</p></div><div class="admonition xdripitem"><p class="admonition-title">Send Calls <span class="symbol"><img src="'+d+'" style="zoom:75%;"></span></p><p> Send call notifications to the band (Android 6+)</p></div><p>You can enable various options to have the watch vibrate on readings, receive alarms or receive notifications as phone calls.</p><div class="admonition xdripitem"><p class="admonition-title">Update BG manually</p></div><p>You can force watchface refresh using Update BG manually.</p><div class="admonition xdripitem"><p class="admonition-title">MiBand Screens / Features</p></div><p>More customizations are available in this menu.</p><div class="admonition xdripitem"><p class="admonition-title">Allow to use custom watchface <span class="symbol"><img src="'+t+'" style="zoom:75%;"></span></p></div><p>You can create your own watchface and modify the background image using these features.<br> Keep them disabled unless you have correctly set the files required in the phone xdrip folder.</p><p>For tips and examples look <a href="https://github.com/twinko" target="_blank" rel="noreferrer">here</a>.</p><div class="admonition xdripitem"><p class="admonition-title">Disable hight MTU values <span class="symbol"><img src="'+t+'" style="zoom:75%;"></span></p></div><p>Disable High MTU can be used when experiencing watchface display issues.</p><h2 id="using-watchdrip" tabindex="-1">Using WatchDrip+ <a class="header-anchor" href="#using-watchdrip" aria-label="Permalink to &quot;Using WatchDrip+&quot;">​</a></h2><h3 id="install-watchdrip" tabindex="-1">Install <a href="https://bigdigital.home.blog/2022/06/16/watchdrip-a-new-application-for-xdrip-watch-integration/" target="_blank" rel="noreferrer">WatchDrip+</a> <a class="header-anchor" href="#install-watchdrip" aria-label="Permalink to &quot;Install [WatchDrip+](https://bigdigital.home.blog/2022/06/16/watchdrip-a-new-application-for-xdrip-watch-integration/)&quot;">​</a></h3><div class="info custom-block"><p class="custom-block-title">Disable MiBand in xDrip if you use WatchDrip+</p><div class="admonition xdripitem"><p class="admonition-title">Use MiBand Band <span class="symbol"><img src="'+t+'" style="zoom:75%;"></span></p></div></div><h3 id="setup-xdrip-1" tabindex="-1">Set up xDrip <a class="header-anchor" href="#setup-xdrip-1" aria-label="Permalink to &quot;Set up xDrip {#setup-xdrip-1}&quot;">​</a></h3><p>Enable Broadcast Service API in Settings -&gt; Inter-app Settings</p><div class="admonition xdrip"><p class="admonition-title"><img src="'+i+'" style="zoom:75%;"></p><p> Settings<br>  <img src="https://raw.githubusercontent.com/NightscoutFoundation/xDrip/master/app/src/main/res/drawable-xhdpi/ic_open_in_app_grey600_48dp.png" style="width:5%;"> Inter-app settings</p></div><div class="admonition xdripitem"><p class="admonition-title">Broadcast Service API <span class="symbol"><img src="'+a+'" style="zoom:75%;"></span></p><p> Enables xDrip communication with third-party applications by using new API</p></div><br><p><a href="https://github.com/NightscoutFoundation/xDrip/releases/tag/2026.11.21" target="_blank" rel="noreferrer"><em>Last modified 23/11/2026</em></a></p>',72)])])}const I=c(y,[["render",f]]);export{z as __pageData,I as default};
